select count(*) from session_messages m
join chat_sessions s on s.id = m.session_id
where m.role = 'assistant' and m.created_at >= #{from}

  and s.agent_id = #{agentId}

select count(*) from session_messages m
join chat_sessions s on s.id = m.session_id
where m.role = 'assistant' and m.answer_type = 'REFUSAL' and m.created_at >= #{from}

  and s.agent_id = #{agentId}
